    slide.addShape(pptx.ShapeType.roundRect, { x:x+2.78, y:yy+0.015, w:w, h:0.14, rectRadius:0.03, fill:{color:'E8EEF7'}, line:{color:'E8EEF7'} });
    slide.addShape(pptx.ShapeType.roundRect, { x:x+2.78, y:yy+0.015, w:w*(value/max), h:0.14, rectRadius:0.03, fill:{color:fill}, line:{color:fill} });
    slide.addText(valueFmt(value), { x:x+2.78+w+0.12, y:yy-0.005, w:0.7, h:0.16, fontSize:7.2, fontFace:'Aptos', bold:true, color:C.ink, margin:0 });
  });
}
function table(slide, rows, x, y, colWs, rowH, opts={}) {
